// =============================================================================
// AnimaI T2I v2.3 — Prompt Builder (standalone, file:// safe)
// Data: window.PROMPTS_DATA / window.MODEL_PRESETS (generated by build.py)
// =============================================================================
'use strict';

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------
const CHAR_SCOPED_SLOTS = new Set([
    'subject', 'hair', 'hair_color', 'eye_color', 'creature_parts', 'expression', 'face_symbols',
    'clothing', 'legwear',
    'accessories', 'pose', 'situation',
    'n_nsfw', 'n_body_type', 'n_expression', 'n_accessories', 'n_pose', 'n_situation', 'n_homosexual',
]);

const LS = {
    favorites: 'anima.favorites',
    favTags: 'anima.favTags',
    presets: 'anima.presets',
    settings: 'anima.settings',
    session: 'anima.session',   // last selection, restored on next visit
    theme: 'theme',
};

const HISTORY_LIMIT = 100;

// Fields of a model preset that the user may edit (everything else, e.g. the
// slot template, always comes from the current build so updates reach users).
const PRESET_EDITABLE = ['quality', 'era', 'ratingAuto', 'negativeBase'];

const FAV_CAT_ID = '__fav__';

const state = {
    // model & settings
    modelId: 'illustrious',
    presets: [],           // MODEL_PRESETS merged with user edits
    nsfwMode: false,
    ratingAuto: true,      // insert safe/nsfw automatically
    qualityAuto: true,     // append preset quality/era tags automatically
    multiChar: false,
    activeSlot: 0,         // 0 = shared/single, 1..3 = character slots

    // selections: Map(prompt -> { weight, locked, cat })
    slots: [new Map(), new Map(), new Map(), new Map()], // [0]=shared, [1..3]=chars
    negativeTags: new Map(),

    // runtime
    favorites: [],
    favTags: [],           // [{ cat, prompt, japanese }]
    cardOpen: new Map(),   // category id -> open? (only after the user toggled it)
    randomExclude: new Set(), // category ids skipped by おまかせ
};

// undo / redo: serialized selection snapshots
const undoHistory = { stack: [], idx: -1, restoring: false };

// ---------------------------------------------------------------------------
// Persistence helpers
// ---------------------------------------------------------------------------
function loadJSON(key, fallback) {
    try {
        const raw = localStorage.getItem(key);
        return raw ? JSON.parse(raw) : fallback;
    } catch (e) {
        return fallback;
    }
}

function saveJSON(key, value) {
    try {
        localStorage.setItem(key, JSON.stringify(value));
    } catch (e) {
        console.error('localStorage save failed', e);
    }
}

function loadString(key) {
    try { return localStorage.getItem(key); } catch (e) { return null; }
}

function saveString(key, value) {
    try { localStorage.setItem(key, value); } catch (e) { /* ignore */ }
}

function defaultPresets() {
    return (window.MODEL_PRESETS || []).map(p => ({
        ...p,
        quality: [...(p.quality || [])],
        template: [...(p.template || [])],
    }));
}

// Merge user edits (stored per id) onto the presets of the current build.
function mergePresets(stored) {
    const base = defaultPresets();
    if (!Array.isArray(stored)) return base;
    for (const p of base) {
        const s = stored.find(x => x && x.id === p.id);
        if (!s) continue;
        for (const f of PRESET_EDITABLE) {
            if (f in s) p[f] = f === 'quality' ? [...(s[f] || [])] : s[f];
        }
    }
    return base;
}

function savePresets() {
    saveJSON(LS.presets, state.presets.map(p => {
        const o = { id: p.id };
        for (const f of PRESET_EDITABLE) o[f] = p[f];
        return o;
    }));
}

function currentPreset() {
    if (!state.presets || state.presets.length === 0) {
        state.presets = defaultPresets();
    }
    return state.presets.find(p => p.id === state.modelId) || state.presets[0];
}

// ---------------------------------------------------------------------------
// Token estimation (CLIP ~77 token limit approximation)
// ---------------------------------------------------------------------------
function countTokens(text) {
    if (!text) return 0;
    let total = 0;
    for (const rawTag of text.split(',')) {
        const tag = rawTag.trim();
        if (!tag || tag === 'BREAK' || isLoraTag(tag)) continue; // LoRA is not text
        total += 1; // comma overhead
        const words = tag.split(/[\s_]+/).filter(Boolean);
        for (const w of words) {
            const clean = w.replace(/[():"']/g, '');
            if (!clean) continue;
            total += clean.length <= 5 ? 1 : 2;
        }
    }
    return total;
}

// BREAK starts a new 75-token chunk, so each chunk is measured on its own.
function countTokenChunks(text) {
    if (!text) return [0];
    return text.split(/(?:^|,)\s*BREAK\s*(?:,|$)/).map(countTokens);
}

// ---------------------------------------------------------------------------
// Data access
// ---------------------------------------------------------------------------
let _catIndex = null;
function allCategories() {
    const d = window.PROMPTS_DATA;
    return [...d.sfw, ...d.nsfw, ...d.negative];
}

function categoryById(id) {
    if (!_catIndex) {
        _catIndex = new Map(allCategories().map(c => [c.id, c]));
    }
    return _catIndex.get(id);
}

function findTagCategory(prompt) {
    for (const c of allCategories()) {
        if (c.tags.some(t => t.prompt === prompt)) return c;
    }
    return null;
}

function tagDefault(cat, prompt) {
    const item = cat && cat.tags ? cat.tags.find(t => t.prompt === prompt) : null;
    const w = item && typeof item.weight === 'number' ? item.weight : 1.0;
    return Math.min(1.9, Math.max(0.5, w));
}

// ---------------------------------------------------------------------------
// Weights & LoRA
// ---------------------------------------------------------------------------
function isLoraTag(prompt) {
    return typeof prompt === 'string' && /^<[^<>]+>$/.test(prompt.trim());
}

function clampWeight(w, lora) {
    if (!isFinite(w)) return 1.0;
    return lora
        ? Math.min(2, Math.max(0, Math.round(w * 100) / 100))
        : Math.min(1.9, Math.max(0.5, Math.round(w * 10) / 10));
}

function formatWeight(w, lora) {
    return lora ? String(Math.round(w * 100) / 100) : w.toFixed(1);
}

// "<lora:name:0.8>" -> { key: "<lora:name>", weight: 0.8 }
function parseLora(text) {
    const m = text.trim().match(/^<\s*([a-z]+)\s*:\s*([^:<>]+?)\s*(?::\s*(-?[\d.]+))?\s*(?::[^<>]*)?>$/i);
    if (!m) return { key: text.trim(), weight: 1 };
    const w = m[3] !== undefined ? parseFloat(m[3]) : 1;
    return { key: `<${m[1].toLowerCase()}:${m[2]}>`, weight: clampWeight(isFinite(w) ? w : 1, true) };
}

// ---------------------------------------------------------------------------
// Prompt text parsing (paste import / manual input)
// ---------------------------------------------------------------------------
// Split on top-level commas / newlines; brackets and "\(" escapes are respected.
function splitPromptTokens(text) {
    const out = [];
    let cur = '', depth = 0;
    for (let i = 0; i < text.length; i++) {
        const c = text[i];
        if (c === '\\' && i + 1 < text.length) { cur += c + text[++i]; continue; }
        if ('([{<'.includes(c)) depth++;
        else if (')]}>'.includes(c)) depth = Math.max(0, depth - 1);
        if ((c === ',' || c === '\n') && depth === 0) { out.push(cur); cur = ''; continue; }
        cur += c;
    }
    out.push(cur);
    return out.map(s => s.trim().replace(/\s+/g, ' ')).filter(Boolean);
}

// true when s[0] is `open` and its matching closer is the last character
function wrappedBy(s, open, close) {
    if (s[0] !== open || s[s.length - 1] !== close) return false;
    let depth = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '\\') { i++; continue; }
        if (s[i] === open) depth++;
        else if (s[i] === close && --depth === 0) return i === s.length - 1;
    }
    return false;
}

// One token -> { tag, weight } | { lora, weight } | { isBreak: true }
function parseToken(tok) {
    let s = tok.trim();
    if (!s) return null;
    if (s === 'BREAK') return { isBreak: true };
    if (isLoraTag(s)) { const l = parseLora(s); return { tag: l.key, weight: l.weight, lora: true }; }
    let w = 1;
    for (let guard = 0; guard < 10; guard++) {
        if (wrappedBy(s, '(', ')')) {
            const inner = s.slice(1, -1);
            const m = inner.match(/^([\s\S]*):\s*(-?[\d.]+)\s*$/);
            if (m && !/\\$/.test(m[1])) { w *= parseFloat(m[2]); s = m[1].trim(); }
            else { w *= 1.1; s = inner.trim(); }
        } else if (wrappedBy(s, '[', ']')) { w /= 1.1; s = s.slice(1, -1).trim(); }
        else if (wrappedBy(s, '{', '}')) { w *= 1.05; s = s.slice(1, -1).trim(); }
        else break;
    }
    if (!s) return null;
    return { tag: s, weight: clampWeight(w, false) };
}

let _tagIndex = null;
// lower-cased prompt (also with "_" <-> " ") -> [category, ...]
function tagIndex() {
    if (_tagIndex) return _tagIndex;
    _tagIndex = new Map();
    const add = (k, cat) => {
        if (!_tagIndex.has(k)) _tagIndex.set(k, []);
        if (!_tagIndex.get(k).includes(cat)) _tagIndex.get(k).push(cat);
    };
    for (const cat of allCategories()) {
        for (const t of cat.tags) {
            const k = t.prompt.toLowerCase();
            add(k, cat);
            add(k.replace(/_/g, ' '), cat);
        }
    }
    return _tagIndex;
}

// Find the catalogue entry for a typed/pasted tag. Returns { cat, prompt } or null.
function lookupTag(tag, negative) {
    const k = tag.toLowerCase();
    const cats = tagIndex().get(k) || tagIndex().get(k.replace(/_/g, ' '));
    if (!cats) return null;
    const pick = cats.find(c => (c.section === 'negative') === negative)
        || cats.find(c => c.section !== 'nsfw' || state.nsfwMode)
        || cats[0];
    const item = pick.tags.find(t => t.prompt.toLowerCase() === k)
        || pick.tags.find(t => t.prompt.toLowerCase().replace(/_/g, ' ') === k.replace(/_/g, ' '));
    return item ? { cat: pick, prompt: item.prompt } : null;
}

function isAutoTag(tag) {
    const k = tag.toLowerCase();
    if (state.qualityAuto) {
        const p = currentPreset();
        if ((p.quality || []).some(q => q.toLowerCase() === k)) return true;
        if (p.era && p.era.toLowerCase() === k) return true;
    }
    if (state.ratingAuto && currentPreset().ratingAuto && (k === 'safe' || k === 'nsfw')) return true;
    return false;
}

// Add free text (comma separated, weights / LoRA allowed) to the selection.
// Known tags join their category; the rest become manual tags.
function addPromptText(text, negative, opts = {}) {
    const res = { known: 0, manual: 0, auto: 0, breaks: 0, dup: 0 };
    const manualPool = negative ? state.negativeTags
        : (state.multiChar && state.activeSlot > 0 ? state.slots[state.activeSlot] : state.slots[0]);
    for (const tok of splitPromptTokens(text)) {
        const p = parseToken(tok);
        if (!p) continue;
        if (p.isBreak) { res.breaks++; continue; }
        if (!negative && opts.skipAuto && !p.lora && isAutoTag(p.tag)) { res.auto++; continue; }
        const found = p.lora ? null : lookupTag(p.tag, negative);
        let pool, prompt, cat;
        if (found) {
            prompt = found.prompt; cat = found.cat.id;
            pool = negative ? state.negativeTags : selectionTarget(found.cat);
        } else {
            prompt = p.tag; cat = 'manual'; pool = manualPool;
        }
        if (pool.has(prompt)) { res.dup++; continue; }
        pool.set(prompt, { weight: p.weight, locked: false, cat });
        found ? res.known++ : res.manual++;
    }
    return res;
}

// Paste import: plain prompt, A1111 "Negative prompt:" block, or a share link.
function importPromptText(text, replace) {
    const shared = decodeShareFromText(text);
    if (shared) {
        restoreSelection(shared);
        return { shared: true };
    }
    let pos = text, neg = null;
    const ni = text.search(/(^|\n)\s*Negative prompt\s*:/i);
    if (ni >= 0) {
        pos = text.slice(0, ni);
        neg = text.slice(ni).replace(/^\s*Negative prompt\s*:/i, '');
    }
    // drop the A1111 parameter line ("Steps: 20, Sampler: ...")
    const cut = s => s.split(/\n\s*Steps\s*:/i)[0];
    pos = cut(pos); if (neg !== null) neg = cut(neg);

    if (replace) {
        state.slots.forEach(m => m.clear());
        if (neg !== null) state.negativeTags.clear();
    }
    const r = addPromptText(pos, false, { skipAuto: true });
    if (neg !== null) {
        const rn = addPromptText(neg, true);
        r.negKnown = rn.known; r.negManual = rn.manual;
    }
    refreshOutputs();
    return r;
}

// ---------------------------------------------------------------------------
// Share links (#s=<base64url of compact JSON>)
// ---------------------------------------------------------------------------
function b64urlEncode(str) {
    const bytes = new TextEncoder().encode(str);
    let bin = '';
    for (let i = 0; i < bytes.length; i += 0x8000) {
        bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
    }
    return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function b64urlDecode(s) {
    const b64 = s.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((s.length + 3) % 4);
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return new TextDecoder().decode(bytes);
}

function encodeShare() {
    const pack = pool => [...pool].map(([p, m]) => {
        const a = [p, m.cat];
        if (m.weight !== 1 || m.locked) a.push(m.weight);
        if (m.locked) a.push(1);
        return a;
    });
    const slots = state.slots.map(pack);
    while (slots.length > 1 && slots[slots.length - 1].length === 0) slots.pop();
    return b64urlEncode(JSON.stringify({
        v: 1,
        m: state.modelId,
        f: (state.nsfwMode ? 1 : 0) | (state.multiChar ? 2 : 0) | (state.ratingAuto ? 4 : 0) | (state.qualityAuto ? 8 : 0),
        s: slots,
        g: pack(state.negativeTags),
    }));
}

function decodeShare(code) {
    const c = JSON.parse(b64urlDecode(code));
    if (!c || c.v !== 1 || !Array.isArray(c.s)) throw new Error('format');
    const unpack = arr => {
        const o = {};
        (Array.isArray(arr) ? arr : []).forEach(a => {
            if (!Array.isArray(a) || typeof a[0] !== 'string') return;
            o[a[0]] = { cat: a[1], weight: a.length > 2 ? a[2] : 1, locked: a[3] === 1 };
        });
        return o;
    };
    const f = Number(c.f) || 0;
    return {
        modelId: c.m,
        nsfwMode: !!(f & 1), multiChar: !!(f & 2), ratingAuto: !!(f & 4), qualityAuto: !!(f & 8),
        slots: [0, 1, 2, 3].map(i => unpack(c.s[i])),
        negative: unpack(c.g),
    };
}

// Accepts a full link, "#s=..." or "s=..."; returns selection data or null.
function decodeShareFromText(text) {
    const m = String(text).trim().match(/^(?:\S*#)?s=([A-Za-z0-9_-]+)$/);
    if (!m) return null;
    try { return decodeShare(m[1]); } catch (e) { return null; }
}

function shareUrl() {
    const base = (location.href || '').split('#')[0];
    return `${base}#s=${encodeShare()}`;
}

// ---------------------------------------------------------------------------
// Undo / redo + session autosave
// ---------------------------------------------------------------------------
function recordHistory() {
    if (undoHistory.restoring) return;
    const snap = JSON.stringify(serializeSelection());
    if (undoHistory.stack[undoHistory.idx] === snap) return;
    undoHistory.stack = undoHistory.stack.slice(0, undoHistory.idx + 1);
    undoHistory.stack.push(snap);
    if (undoHistory.stack.length > HISTORY_LIMIT) undoHistory.stack.shift();
    undoHistory.idx = undoHistory.stack.length - 1;
    saveString(LS.session, snap);
    updateHistoryButtons();
}

function applyHistory() {
    undoHistory.restoring = true;
    try {
        restoreSelection(JSON.parse(undoHistory.stack[undoHistory.idx]));
    } finally {
        undoHistory.restoring = false;
    }
    saveString(LS.session, undoHistory.stack[undoHistory.idx]);
    updateHistoryButtons();
}

function undo() {
    if (undoHistory.idx <= 0) return false;
    undoHistory.idx--;
    applyHistory();
    return true;
}

function redo() {
    if (undoHistory.idx >= undoHistory.stack.length - 1) return false;
    undoHistory.idx++;
    applyHistory();
    return true;
}

function updateHistoryButtons() {
    const u = document.getElementById('undo-btn');
    const r = document.getElementById('redo-btn');
    if (u) u.disabled = undoHistory.idx <= 0;
    if (r) r.disabled = undoHistory.idx >= undoHistory.stack.length - 1;
}

// ---------------------------------------------------------------------------
// Toast (short status messages, announced to screen readers)
// ---------------------------------------------------------------------------
let _toastTimer = null;
function toast(msg) {
    const el = document.getElementById('toast');
    if (!el) return;
    el.textContent = msg;
    el.classList.add('show');
    clearTimeout(_toastTimer);
    _toastTimer = setTimeout(() => el.classList.remove('show'), 2600);
}

// ---------------------------------------------------------------------------
// Selection logic
// ---------------------------------------------------------------------------
function selectionTarget(cat) {
    // negative section -> negative pool
    if (cat && cat.section === 'negative') return state.negativeTags;
    // char-scoped category in multi-char mode -> active character slot
    if (state.multiChar && cat && CHAR_SCOPED_SLOTS.has(cat.id) && state.activeSlot > 0) {
        return state.slots[state.activeSlot];
    }
    return state.slots[0];
}

function toggleTag(cat, prompt) {
    const target = selectionTarget(cat);
    if (target.has(prompt)) {
        target.delete(prompt);
    } else {
        target.set(prompt, { weight: tagDefault(cat, prompt), locked: false, cat: cat.id });
    }
    refreshOutputs();
}

function removeTag(pool, prompt) {
    pool.delete(prompt);
    refreshOutputs();
}

function setWeight(pool, prompt, delta) {
    const meta = pool.get(prompt);
    if (!meta) return;
    meta.weight = clampWeight(Math.round((meta.weight + delta) * 100) / 100, isLoraTag(prompt));
    refreshOutputs();
}

function toggleLock(pool, prompt) {
    const meta = pool.get(prompt);
    if (!meta) return;
    meta.locked = !meta.locked;
    renderSelectedChips();
    recordHistory();
}

// Move `src` before/after `target` inside one pool (Map keeps insertion order,
// which is the order tags are emitted within their slot).
function reorderPool(pool, src, target, after) {
    if (src === target || !pool.has(src) || !pool.has(target)) return;
    const entries = [...pool.entries()];
    const from = entries.findIndex(([p]) => p === src);
    const [moved] = entries.splice(from, 1);
    let to = entries.findIndex(([p]) => p === target);
    if (after) to++;
    entries.splice(to, 0, moved);
    pool.clear();
    entries.forEach(([p, m]) => pool.set(p, m));
    refreshOutputs();
}

// Reflect the selection on every rendered tag button (category lists and the
// favorite-tags card can show the same tag more than once).
function syncTagButtons() {
    if (!document.querySelectorAll) return;
    document.querySelectorAll('.prompt-tag[data-prompt]').forEach(btn => {
        const cat = categoryById(btn.dataset.cat);
        if (!cat) return;
        const prompt = btn.dataset.prompt;
        const target = selectionTarget(cat);
        const active = target.has(prompt);
        const elsewhere = !active && cat.section !== 'negative'
            && state.slots.some(pool => pool !== target && pool.has(prompt));
        btn.classList.toggle('active', active);
        btn.classList.toggle('in-other-slot', elsewhere);
        btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
}

// ---------------------------------------------------------------------------
// Favorite tags
// ---------------------------------------------------------------------------
function isFavTag(catId, prompt) {
    return state.favTags.some(f => f.cat === catId && f.prompt === prompt);
}

function toggleFavTag(cat, item) {
    if (isFavTag(cat.id, item.prompt)) {
        state.favTags = state.favTags.filter(f => !(f.cat === cat.id && f.prompt === item.prompt));
    } else {
        state.favTags.push({ cat: cat.id, prompt: item.prompt, japanese: item.japanese });
    }
    saveJSON(LS.favTags, state.favTags);
    renderCategories();
    refreshOutputs();
}

// Favorite tags of a section that still exist in the current data.
function favTagsForSection(section) {
    return state.favTags
        .map(f => {
            const cat = categoryById(f.cat);
            if (!cat || cat.section !== section) return null;
            const item = cat.tags.find(t => t.prompt === f.prompt);
            return item ? { cat, item } : null;
        })
        .filter(Boolean);
}

// ---------------------------------------------------------------------------
// Prompt assembly engine
// ---------------------------------------------------------------------------
function applyWeight(prompt, meta) {
    if (isLoraTag(prompt)) {
        // <lora:name> + weight -> <lora:name:0.8>
        const m = prompt.match(/^<([^:<>]+):([^:<>]+)>$/);
        const w = meta && typeof meta.weight === 'number' ? meta.weight : 1;
        return m ? `<${m[1]}:${m[2]}:${formatWeight(w, true)}>` : prompt;
    }
    if (meta && meta.weight && meta.weight !== 1.0) {
        return `(${prompt}:${meta.weight.toFixed(1)})`;
    }
    return prompt;
}

function collectSlotTags(slotMap, slotName, preset) {
    // returns array of {prompt, meta} belonging to slotName
    const out = [];
    slotMap.forEach((meta, prompt) => {
        const cat = categoryById(meta.cat);
        const slot = cat ? cat.slot : 'composition';
        if (slot === slotName) out.push({ prompt, meta });
    });
    return out;
}

// Template order plus any slot the template does not know about, so no
// selected tag is ever silently dropped. Unknown slots go before "quality".
// LoRA / embeddings always go last.
function orderedSlots(template, groups) {
    const extra = Object.keys(groups).filter(s => !template.includes(s) && s !== 'lora');
    const order = [...template];
    if (extra.length) {
        const qi = order.indexOf('quality');
        order.splice(qi >= 0 ? qi : order.length, 0, ...extra);
    }
    if (groups.lora) order.push('lora');
    return order;
}

function groupPool(pool, template, emitted) {
    const groups = {};
    for (const slotName of template) groups[slotName] = [];
    pool.forEach((meta, prompt) => {
        const cat = categoryById(meta.cat);
        const slot = isLoraTag(prompt) ? 'lora' : cat ? cat.slot : 'composition';
        if (!groups[slot]) groups[slot] = [];
        const parts = prompt.split(',').map(s => s.trim()).filter(Boolean);
        const kept = [];
        for (const p of parts) {
            const k = p.toLowerCase();
            if (emitted.has(k)) continue;
            emitted.add(k);
            kept.push(p);
        }
        if (kept.length === 0) return; // fully duplicate entry
        groups[slot].push(applyWeight(kept.join(', '), meta));
    });
    return groups;
}

function autoRatingTag() {
    if (!state.ratingAuto || !currentPreset().ratingAuto) return null;
    return state.nsfwMode ? 'nsfw' : 'safe';
}

function autoQualityTags() {
    if (!state.qualityAuto) return [];
    const p = currentPreset();
    return p.quality || [];
}

function autoEraTag() {
    if (!state.qualityAuto) return null;
    const p = currentPreset();
    return p.era || null;
}

function pushUnique(arr, tag, front) {
    const k = tag.toLowerCase();
    if (arr.some(t => t.toLowerCase() === k)) return;
    if (front) arr.unshift(tag); else arr.push(tag);
}

function assemblePositive() {
    const preset = currentPreset();
    const template = preset.template || [];
    const emitted = new Set(); // final-prompt level tag dedupe

    const groups = groupPool(state.slots[0], template, emitted);
    for (const s of ['rating', 'quality', 'era']) if (!groups[s]) groups[s] = [];

    const rating = autoRatingTag();
    if (rating && !emitted.has(rating)) { pushUnique(groups.rating, rating, true); emitted.add(rating); }
    for (const q of autoQualityTags()) {
        if (!emitted.has(q.toLowerCase())) { pushUnique(groups.quality, q); emitted.add(q.toLowerCase()); }
    }
    const era = autoEraTag();
    if (era && !emitted.has(era.toLowerCase())) { pushUnique(groups.era, era); emitted.add(era.toLowerCase()); }

    const order = orderedSlots(template, groups);
    let result = [];
    if (!state.multiChar) {
        result = order.flatMap(s => groups[s] || []);
    } else {
        // multi-character: subject & rating first, then BREAK-separated chars,
        // then remaining shared slots in template order
        const head = ['subject', 'character', 'rating', 'rating_adj'];
        for (const s of head) result.push(...(groups[s] || []));
        const charBlocks = [];
        const charEmitted = new Set(emitted); // shared tags already emitted
        for (let i = 1; i <= 3; i++) {
            const pool = state.slots[i];
            if (pool.size === 0) continue;
            const charGroups = groupPool(pool, template, charEmitted);
            const block = orderedSlots(template, charGroups).flatMap(s => charGroups[s] || []);
            if (block.length) charBlocks.push(block.join(', '));
        }
        if (charBlocks.length) result.push(charBlocks.join(', BREAK, '));
        for (const s of order) {
            if (head.includes(s)) continue;
            result.push(...(groups[s] || []));
        }
    }
    return result.filter(Boolean).join(', ');
}

function assembleNegative() {
    const out = [];
    const emittedNeg = new Set();
    state.negativeTags.forEach((meta, prompt) => {
        const parts = prompt.split(',').map(s => s.trim()).filter(Boolean);
        const seenLocal = new Set();
        const kept = parts.filter(p => {
            const k = p.toLowerCase();
            if (seenLocal.has(k) || emittedNeg.has(k)) return false;
            seenLocal.add(k);
            return true;
        });
        if (kept.length === 0) return;
        kept.forEach(p => emittedNeg.add(p.toLowerCase()));
        out.push(applyWeight(kept.join(', '), meta));
    });
    return out.join(', ');
}

// ---------------------------------------------------------------------------
// Rendering: categories
// ---------------------------------------------------------------------------
function renderCategories() {
    const d = window.PROMPTS_DATA;
    renderCategoryList(d.sfw, document.getElementById('sfw-categories'), 'sfw');
    renderCategoryList(d.nsfw, document.getElementById('nsfw-categories'), 'nsfw');
    renderCategoryList(d.negative, document.getElementById('negative-categories'), 'negative');
    applySearchFilter();
    syncTagButtons();
}

function makeCategoryCard(id, label, count, entries, isOpen) {
    const card = document.createElement('div');
    card.className = 'category-card' + (isOpen ? '' : ' collapsed');
    card.dataset.cat = id;

    const bodyId = `cat-body-${id}`;
    const title = document.createElement('button');
    title.type = 'button';
    title.className = 'category-title';
    title.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    title.setAttribute('aria-controls', bodyId);
    const titleText = document.createElement('span');
    titleText.className = 'category-title-text';
    titleText.textContent = label;
    const countEl = document.createElement('span');
    countEl.className = 'category-count';
    countEl.textContent = `(${count})`;
    titleText.appendChild(document.createTextNode(' '));
    titleText.appendChild(countEl);
    title.appendChild(titleText);
    title.addEventListener('click', () => {
        // a card opened by an active search counts as open
        const wasOpen = !card.classList.contains('collapsed') || card.classList.contains('search-open');
        card.classList.remove('search-open');
        card.classList.toggle('collapsed', wasOpen);
        title.setAttribute('aria-expanded', wasOpen ? 'false' : 'true');
        state.cardOpen.set(id, !wasOpen);
    });

    const body = document.createElement('div');
    body.className = 'category-body';
    body.id = bodyId;
    const inner = document.createElement('div');
    inner.className = 'category-body-inner';
    entries.forEach(({ cat, item }) => inner.appendChild(createTagElement(cat, item)));

    const none = document.createElement('div');
    none.className = 'loading no-match';
    none.textContent = '一致するタグなし';
    none.hidden = true;
    inner.appendChild(none);

    body.appendChild(inner);
    card.appendChild(title);
    card.appendChild(body);
    return card;
}

function renderCategoryList(categories, containerEl, section) {
    if (!containerEl) return;
    containerEl.innerHTML = '';
    if (!categories || categories.length === 0) {
        containerEl.innerHTML = '<div class="loading">データがありません。</div>';
        return;
    }

    const isOpen = (id, dflt) => state.cardOpen.has(id) ? state.cardOpen.get(id) : dflt;

    // favorite tags of this section, pinned on top
    const favEntries = favTagsForSection(section);
    if (favEntries.length > 0) {
        const favId = FAV_CAT_ID + section;
        const card = makeCategoryCard(favId, '★ お気に入りタグ', favEntries.length, favEntries, isOpen(favId, true));
        card.classList.add('fav-card');
        containerEl.appendChild(card);
    }

    categories.forEach((cat, index) => {
        const dflt = section !== 'nsfw' && index === 0 && favEntries.length === 0;
        containerEl.appendChild(makeCategoryCard(cat.id, cat.name, cat.tags.length,
            cat.tags.map(item => ({ cat, item })), isOpen(cat.id, dflt)));
    });
}

// Show/hide tag buttons in place (no re-render, keeps open/closed state).
// While a query is active, categories with matches are opened automatically.
function applySearchFilter() {
    const input = document.getElementById('tag-search-input');
    const filter = ((input && input.value) || '').trim().toLowerCase();
    document.querySelectorAll('.category-card').forEach(card => {
        const tags = card.querySelectorAll('.prompt-tag-item');
        let visible = 0;
        tags.forEach(el => {
            const hit = !filter || (el.dataset.search || '').includes(filter);
            el.hidden = !hit;
            if (hit) visible++;
        });
        const none = card.querySelector('.no-match');
        if (none) none.hidden = !(filter && visible === 0);
        const countEl = card.querySelector('.category-count');
        if (countEl) countEl.textContent = filter ? `(${visible}/${tags.length})` : `(${tags.length})`;
        card.classList.toggle('search-open', !!filter && visible > 0);
        card.classList.toggle('search-empty', !!filter && visible === 0);
        const title = card.querySelector('.category-title');
        if (title) {
            const open = !card.classList.contains('collapsed') || card.classList.contains('search-open');
            title.setAttribute('aria-expanded', open ? 'true' : 'false');
        }
    });
}

function createTagElement(cat, item) {
    const wrap = document.createElement('span');
    wrap.className = 'prompt-tag-item';
    wrap.dataset.search = `${item.japanese}\n${item.prompt}`.toLowerCase();

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'prompt-tag';
    btn.dataset.cat = cat.id;
    btn.dataset.prompt = item.prompt;

    const jp = document.createElement('span');
    jp.className = 'jp-name';
    jp.textContent = item.japanese;

    const en = document.createElement('span');
    en.className = 'en-name';
    en.textContent = item.prompt;

    btn.appendChild(jp);
    btn.appendChild(en);
    btn.addEventListener('click', (e) => {
        e.stopPropagation();
        toggleTag(cat, item.prompt);
    });

    const fav = isFavTag(cat.id, item.prompt);
    const star = document.createElement('button');
    star.type = 'button';
    star.className = 'tag-fav-btn' + (fav ? ' is-fav' : '');
    star.textContent = fav ? '★' : '☆';
    star.title = fav ? 'お気に入りタグから外す' : 'お気に入りタグに追加';
    star.setAttribute('aria-label', `${item.japanese} を${star.title}`);
    star.setAttribute('aria-pressed', fav ? 'true' : 'false');
    star.addEventListener('click', (e) => {
        e.stopPropagation();
        toggleFavTag(cat, item);
    });

    wrap.appendChild(btn);
    wrap.appendChild(star);
    return wrap;
}

// ---------------------------------------------------------------------------
// Rendering: selected chips (with weight / lock / remove)
// ---------------------------------------------------------------------------
function renderSelectedChips() {
    const wrap = document.getElementById('selected-chips');
    if (!wrap) return;
    wrap.innerHTML = '';

    const mkChips = (pool, label) => {
        if (pool.size === 0) return;
        const group = document.createElement('div');
        group.className = 'chip-group';
        const gLabel = document.createElement('div');
        gLabel.className = 'chip-group-label';
        gLabel.textContent = label;
        group.appendChild(gLabel);

        pool.forEach((meta, prompt) => {
            const chip = document.createElement('div');
            const catClass = !meta.cat || meta.cat === 'manual' ? ''
                : meta.cat.startsWith('n_') ? ' cat-nsfw'
                : meta.cat === 'negative_prompt' ? ' cat-negative'
                : ' cat-' + meta.cat;
            const lora = isLoraTag(prompt);
            chip.className = 'chip' + (meta.locked ? ' locked' : '') + catClass + (lora ? ' chip-lora' : '');
            attachChipDrag(chip, pool, prompt);

            const name = document.createElement('span');
            name.className = 'chip-name';
            name.textContent = prompt;
            name.title = lora ? `${prompt}（LoRA・ドラッグで並べ替え）` : `${prompt}（ドラッグで並べ替え）`;
            chip.appendChild(name);

            // weight: every tag, and LoRA of the <type:name> form
            const weighted = !lora || /^<[^:<>]+:[^:<>]+>$/.test(prompt);
            if (weighted) {
                const minus = document.createElement('button');
                minus.textContent = '−';
                minus.title = '重み -0.1';
                minus.addEventListener('click', () => setWeight(pool, prompt, -0.1));
                const w = document.createElement('span');
                w.className = 'chip-weight';
                w.textContent = formatWeight(meta.weight, lora);
                const plus = document.createElement('button');
                plus.textContent = '+';
                plus.title = '重み +0.1';
                plus.addEventListener('click', () => setWeight(pool, prompt, +0.1));
                chip.appendChild(minus);
                chip.appendChild(w);
                chip.appendChild(plus);
            }

            {
                const cat = categoryById(meta.cat);
                if (cat) {
                    const fav = isFavTag(cat.id, prompt);
                    const star = document.createElement('button');
                    star.className = 'chip-fav' + (fav ? ' is-fav' : '');
                    star.textContent = fav ? '★' : '☆';
                    star.title = fav ? 'お気に入りタグから外す' : 'お気に入りタグに追加';
                    star.addEventListener('click', () => {
                        const item = cat.tags.find(t => t.prompt === prompt) || { prompt, japanese: prompt };
                        toggleFavTag(cat, item);
                    });
                    chip.appendChild(star);
                }
            }

            const lock = document.createElement('button');
            lock.textContent = meta.locked ? '🔒' : '🔓';
            lock.title = 'ランダム生成時に固定';
            lock.addEventListener('click', () => toggleLock(pool, prompt));
            chip.appendChild(lock);

            const del = document.createElement('button');
            del.textContent = '×';
            del.title = '削除';
            del.addEventListener('click', () => removeTag(pool, prompt));
            chip.appendChild(del);

            group.appendChild(chip);
        });
        wrap.appendChild(group);
    };

    if (state.multiChar) {
        mkChips(state.slots[0], '共通');
        for (let i = 1; i <= 3; i++) {
            if (state.slots[i].size > 0) mkChips(state.slots[i], `キャラ${i}`);
        }
    } else {
        mkChips(state.slots[0], '選択中');
    }
    mkChips(state.negativeTags, 'ネガティブ');
}

// Drag & drop reordering inside one pool (desktop pointer).
let _dragSrc = null;
function attachChipDrag(chip, pool, prompt) {
    chip.draggable = true;
    chip.addEventListener('dragstart', (e) => {
        _dragSrc = { pool, prompt };
        chip.classList.add('dragging');
        try { e.dataTransfer.effectAllowed = 'move'; e.dataTransfer.setData('text/plain', prompt); } catch (err) { /* ignore */ }
    });
    chip.addEventListener('dragend', () => {
        _dragSrc = null;
        document.querySelectorAll('.chip.dragging, .chip.drop-before, .chip.drop-after')
            .forEach(c => c.classList.remove('dragging', 'drop-before', 'drop-after'));
    });
    const after = (e) => {
        const r = chip.getBoundingClientRect();
        return e.clientX > r.left + r.width / 2;
    };
    chip.addEventListener('dragover', (e) => {
        if (!_dragSrc || _dragSrc.pool !== pool || _dragSrc.prompt === prompt) return;
        e.preventDefault();
        const a = after(e);
        chip.classList.toggle('drop-after', a);
        chip.classList.toggle('drop-before', !a);
    });
    chip.addEventListener('dragleave', () => chip.classList.remove('drop-before', 'drop-after'));
    chip.addEventListener('drop', (e) => {
        if (!_dragSrc || _dragSrc.pool !== pool) return;
        e.preventDefault();
        const src = _dragSrc.prompt;
        _dragSrc = null;
        reorderPool(pool, src, prompt, after(e));
    });
}

// ---------------------------------------------------------------------------
// Rendering: outputs & token counters
// ---------------------------------------------------------------------------
function tokenLabel(text) {
    const chunks = countTokenChunks(text);
    const max = Math.max(...chunks);
    const label = chunks.length > 1
        ? `約 ${chunks.join(' + ')} トークン (BREAK ${chunks.length}ブロック・各75まで)`
        : `約 ${chunks[0]} / 75 トークン`;
    const cls = 'token-count' + (max > 75 ? ' over' : max > 60 ? ' warn' : '');
    return { label, cls };
}

function refreshOutputs() {
    const pos = assemblePositive();
    const neg = assembleNegative();
    document.getElementById('positive-prompt-output').value = pos;
    document.getElementById('negative-prompt-output').value = neg;

    const posEl = document.getElementById('pos-token-count');
    const negEl = document.getElementById('neg-token-count');
    const p = tokenLabel(pos);
    const n = tokenLabel(neg);
    posEl.textContent = p.label;
    posEl.className = p.cls;
    negEl.textContent = n.label;
    negEl.className = n.cls;

    // model badge on positive card
    const badge = document.getElementById('model-badge');
    if (badge) badge.textContent = currentPreset().name;

    // mobile copy bar mirrors the positive token count
    const mobileTok = document.getElementById('mobile-token-count');
    if (mobileTok) {
        mobileTok.textContent = p.label.replace(/^約 /, '').split(' トークン')[0] + ' tok';
        mobileTok.title = p.label;
        mobileTok.className = 'mobile-token ' + p.cls;
    }

    renderSelectedChips();
    syncTagButtons();
    recordHistory();
}

// ---------------------------------------------------------------------------
// Random generation (lock-aware)
// ---------------------------------------------------------------------------
const RANDOM_CATEGORIES = [
    'subject', 'hair', 'hair_color', 'eye_color', 'creature_parts', 'expression', 'face_symbols',
    'clothing', 'legwear',
    'accessories', 'pose', 'situation', 'composition', 'background',
    'background_style', 'effect', 'art_style', 'era',
    'n_nsfw', 'n_body_type', 'n_expression', 'n_accessories', 'n_pose', 'n_situation', 'n_homosexual',
];

function randomize() {
    for (const catId of RANDOM_CATEGORIES) {
        const cat = categoryById(catId);
        if (!cat || cat.section === 'negative') continue;
        if (catId.startsWith('n_') && !state.nsfwMode) continue;
        if (state.randomExclude.has(catId)) continue;

        const pool = selectionTarget(cat);

        // keep locked tags of this category
        const locked = [];
        pool.forEach((meta, prompt) => {
            if (meta.cat === catId) {
                if (meta.locked) locked.push({ prompt, meta });
                pool.delete(prompt);
            }
        });

        if (locked.length === 0) {
            const skipChance = catId === 'creature_parts' ? 0.7
                : catId === 'face_symbols' ? 0.6
                : ['accessories', 'effect', 'art_style', 'era', 'situation', 'legwear'].includes(catId) ? 0.35
                : (catId.startsWith('n_') && catId !== 'n_nsfw') ? 0.5
                : 0.1;
            const mustPick = catId === 'subject' || catId === 'hair' || catId === 'expression';
            if (mustPick || Math.random() >= skipChance) {
                const pick = cat.tags[Math.floor(Math.random() * cat.tags.length)];
                if (pick) pool.set(pick.prompt, { weight: tagDefault(cat, pick.prompt), locked: false, cat: catId });
            }
        }
        locked.forEach(l => pool.set(l.prompt, l.meta));
    }
    refreshOutputs();
}

// ---------------------------------------------------------------------------
// Favorites (localStorage)
// ---------------------------------------------------------------------------
function serializeSelection() {
    const ser = m => {
        const o = {};
        m.forEach((meta, prompt) => o[prompt] = { ...meta });
        return o;
    };
    return {
        modelId: state.modelId,
        nsfwMode: state.nsfwMode,
        multiChar: state.multiChar,
        ratingAuto: state.ratingAuto,
        qualityAuto: state.qualityAuto,
        slots: state.slots.map(ser),
        negative: ser(state.negativeTags),
    };
}

function sanitizeMeta(meta, prompt) {
    const m = meta && typeof meta === 'object' ? meta : {};
    const lora = isLoraTag(prompt);
    let w = Number(m.weight);
    if (m.weight === undefined || m.weight === null || !isFinite(w) || (!lora && w <= 0)) w = 1.0;
    w = clampWeight(w, lora);
    return { weight: w, locked: !!m.locked, cat: typeof m.cat === 'string' ? m.cat : 'manual' };
}

function restoreSelection(data) {
    if (!data || typeof data !== 'object') return;
    const deser = o => {
        const m = new Map();
        if (o && typeof o === 'object') {
            Object.entries(o).forEach(([prompt, meta]) => m.set(prompt, sanitizeMeta(meta, prompt)));
        }
        return m;
    };
    if (data.modelId && state.presets.some(p => p.id === data.modelId)) state.modelId = data.modelId;
    state.nsfwMode = !!data.nsfwMode;
    state.multiChar = !!data.multiChar;
    state.activeSlot = 0;
    state.ratingAuto = data.ratingAuto !== false;
    state.qualityAuto = data.qualityAuto !== false;
    state.slots = [0, 1, 2, 3].map(i => deser(Array.isArray(data.slots) ? data.slots[i] : {}));
    state.negativeTags = deser(data.negative);
    saveSettings();
    syncControlsFromState();
    refreshOutputs();
}

function hasSelection() {
    return state.slots.some(s => s.size > 0) || state.negativeTags.size > 0;
}

function renderFavorites() {
    const listEl = document.getElementById('favorites-list');
    if (!listEl) return;
    listEl.innerHTML = '';
    if (state.favorites.length === 0) {
        listEl.innerHTML = '<div class="no-favorites">保存されたお気に入りはまだありません。</div>';
        return;
    }
    state.favorites.forEach(preset => {
        const item = document.createElement('div');
        item.className = 'favorite-item';
        item.tabIndex = 0;
        item.setAttribute('role', 'button');

        const content = document.createElement('div');
        content.className = 'favorite-item-content';
        const nameEl = document.createElement('div');
        nameEl.className = 'favorite-item-name';
        nameEl.textContent = '⭐ ' + preset.name;
        const metaEl = document.createElement('div');
        metaEl.className = 'favorite-item-meta';
        const totalTags = (preset.data?.slots || []).reduce((a, s) => a + Object.keys(s || {}).length, 0)
            + Object.keys(preset.data?.negative || {}).length;
        const tagSpan = document.createElement('span');
        tagSpan.textContent = `タグ: ${totalTags}`;
        const modelSpan = document.createElement('span');
        const model = state.presets.find(p => p.id === preset.data?.modelId);
        modelSpan.textContent = model ? model.name : String(preset.data?.modelId || '');
        metaEl.appendChild(tagSpan);
        metaEl.appendChild(document.createTextNode(' '));
        metaEl.appendChild(modelSpan);
        content.appendChild(nameEl);
        content.appendChild(metaEl);

        const load = () => {
            if (hasSelection() && !confirm(`「${preset.name}」を読み込みます。現在の選択は置き換えられます。よろしいですか？`)) return;
            restoreSelection(preset.data);
        };
        item.addEventListener('click', load);
        item.addEventListener('keydown', (e) => {
            if (e.target === item && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); load(); }
        });

        const actions = document.createElement('div');
        actions.className = 'favorite-item-actions';
        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'fav-delete-btn';
        deleteBtn.textContent = '×';
        deleteBtn.title = '削除';
        deleteBtn.setAttribute('aria-label', `お気に入り「${preset.name}」を削除`);
        deleteBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            if (confirm(`お気に入り「${preset.name}」を削除してもよろしいですか？`)) {
                state.favorites = state.favorites.filter(f => f.name !== preset.name);
                saveJSON(LS.favorites, state.favorites);
                renderFavorites();
            }
        });
        actions.appendChild(deleteBtn);

        item.appendChild(content);
        item.appendChild(actions);
        listEl.appendChild(item);
    });
}

function saveFavorite() {
    const inputEl = document.getElementById('favorite-name-input');
    const name = inputEl.value.trim();
    if (!name) { alert('お気に入りの名前を入力してください。'); return; }
    if (!hasSelection()) { alert('プロンプトが選択されていません。'); return; }
    if (state.favorites.some(f => f.name === name)) {
        if (!confirm(`「${name}」を上書きしますか？`)) return;
        state.favorites = state.favorites.filter(f => f.name !== name);
    }
    state.favorites.push({ name, data: serializeSelection() });
    saveJSON(LS.favorites, state.favorites);
    inputEl.value = '';
    renderFavorites();
}

function exportFavorites() {
    const payload = { app: 'AnimaI T2I', version: 2, favorites: state.favorites, favoriteTags: state.favTags };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'animaI-favorites.json';
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}

// Accepts the v2 object format and the legacy plain-array format.
function mergeImportedFavorites(imported) {
    let favs, tags;
    if (Array.isArray(imported)) { favs = imported; tags = []; }
    else if (imported && typeof imported === 'object') {
        favs = Array.isArray(imported.favorites) ? imported.favorites : [];
        tags = Array.isArray(imported.favoriteTags) ? imported.favoriteTags : [];
    } else throw new Error('format');

    const names = new Set(state.favorites.map(f => f.name));
    let added = 0;
    for (const f of favs) {
        if (!f || typeof f.name !== 'string' || !f.name || !f.data || typeof f.data !== 'object') continue;
        let name = f.name;
        for (let i = 2; names.has(name); i++) name = `${f.name} (${i})`;
        names.add(name);
        state.favorites.push({ name, data: f.data });
        added++;
    }
    let addedTags = 0;
    for (const t of tags) {
        if (!t || typeof t.cat !== 'string' || typeof t.prompt !== 'string') continue;
        if (isFavTag(t.cat, t.prompt)) continue;
        state.favTags.push({ cat: t.cat, prompt: t.prompt, japanese: String(t.japanese || t.prompt) });
        addedTags++;
    }
    return { added, addedTags };
}

function importFavorites(file) {
    const reader = new FileReader();
    reader.onload = () => {
        try {
            const res = mergeImportedFavorites(JSON.parse(reader.result));
            saveJSON(LS.favorites, state.favorites);
            saveJSON(LS.favTags, state.favTags);
            renderFavorites();
            renderCategories();
            refreshOutputs();
            alert(`読み込み完了: お気に入り ${res.added} 件 / お気に入りタグ ${res.addedTags} 件`);
        } catch (e) {
            alert('読み込みに失敗しました。JSON形式が正しくありません。');
        }
    };
    reader.readAsText(file);
}

// ---------------------------------------------------------------------------
// Preset editor modal
// ---------------------------------------------------------------------------
let _modalReturnFocus = null;

function presetField(labelText, input) {
    const label = document.createElement('label');
    label.appendChild(document.createTextNode(labelText));
    label.appendChild(input);
    return label;
}

function renderPresetEditor() {
    const list = document.getElementById('preset-editor-list');
    list.innerHTML = '';
    state.presets.forEach(p => {
        const row = document.createElement('div');
        row.className = 'preset-editor-row';

        const nameEl = document.createElement('div');
        nameEl.className = 'preset-editor-name';
        nameEl.textContent = p.name;
        row.appendChild(nameEl);

        const quality = document.createElement('input');
        quality.type = 'text';
        quality.value = (p.quality || []).join(', ');
        quality.addEventListener('change', () => {
            p.quality = quality.value.split(',').map(s => s.trim()).filter(Boolean);
            savePresets(); refreshOutputs();
        });
        row.appendChild(presetField('品質タグ（カンマ区切り）', quality));

        const era = document.createElement('input');
        era.type = 'text';
        era.value = p.era || '';
        era.addEventListener('change', () => {
            p.era = era.value.trim() || null;
            savePresets(); refreshOutputs();
        });
        row.appendChild(presetField('年代タグ（空欄で無効）', era));

        const rating = document.createElement('input');
        rating.type = 'checkbox';
        rating.checked = !!p.ratingAuto;
        rating.addEventListener('change', () => {
            p.ratingAuto = rating.checked;
            savePresets(); refreshOutputs();
        });
        row.appendChild(presetField('レーティング自動挿入', rating));

        const neg = document.createElement('textarea');
        neg.rows = 2;
        neg.value = p.negativeBase || '';
        neg.addEventListener('change', () => {
            p.negativeBase = neg.value.trim();
            savePresets(); refreshOutputs();
        });
        row.appendChild(presetField('推奨ネガティブ（初期値）', neg));

        list.appendChild(row);
    });
}

let _openModalId = null;

function openModal(id, focusSel) {
    if (_openModalId) closeModal();
    _modalReturnFocus = document.activeElement;
    const modal = document.getElementById(id);
    modal.style.display = 'flex';
    _openModalId = id;
    const first = modal.querySelector(focusSel || 'input, textarea, button');
    if (first && first.focus) first.focus();
}

function closeModal() {
    if (!_openModalId) return;
    document.getElementById(_openModalId).style.display = 'none';
    _openModalId = null;
    if (_modalReturnFocus && _modalReturnFocus.focus) _modalReturnFocus.focus();
}

function openPresetModal() {
    renderPresetEditor();
    openModal('preset-modal');
}

function closePresetModal() {
    if (_openModalId === 'preset-modal') closeModal();
}

// ---------------------------------------------------------------------------
// Paste import dialog
// ---------------------------------------------------------------------------
function runPasteImport() {
    const ta = document.getElementById('import-text');
    const text = ta.value.trim();
    if (!text) { closeModal(); return; }
    const replace = !!document.querySelector('input[name="import-mode"][value="replace"]:checked');
    const r = importPromptText(text, replace);
    ta.value = '';
    closeModal();
    if (r.shared) { toast('共有リンクの内容を読み込みました'); return; }
    const parts = [`カタログ一致 ${r.known}`, `手入力扱い ${r.manual}`];
    if (r.negKnown !== undefined) parts.push(`ネガティブ ${r.negKnown + r.negManual}`);
    if (r.auto) parts.push(`自動挿入タグ ${r.auto} は省略`);
    if (r.breaks) parts.push('BREAK は無視');
    toast('読み込み: ' + parts.join(' / '));
}

