function renderRandomConfig() {
    const list = document.getElementById('random-config-list');
    if (!list) return;
    list.innerHTML = '';
    RANDOM_CATEGORIES.forEach(id => {
        const cat = categoryById(id);
        if (!cat || (id.startsWith('n_') && !state.nsfwMode)) return;
        const label = document.createElement('label');
        label.className = 'random-config-item';
        const cb = document.createElement('input');
        cb.type = 'checkbox';
        cb.checked = !state.randomExclude.has(id);
        cb.addEventListener('change', () => {
            if (cb.checked) state.randomExclude.delete(id); else state.randomExclude.add(id);
            saveSettings();
        });
        label.appendChild(cb);
        label.appendChild(document.createTextNode(cat.name));
        list.appendChild(label);
    });
}

function setAllRandomCats(on) {
    RANDOM_CATEGORIES.forEach(id => {
        if (id.startsWith('n_') && !state.nsfwMode) return;
        if (on) state.randomExclude.delete(id); else state.randomExclude.add(id);
    });
    saveSettings();
    renderRandomConfig();
}

// ---------------------------------------------------------------------------
// Tag autocomplete for the manual inputs
// ---------------------------------------------------------------------------
function suggestCandidates(query, negative, limit = 8) {
    const q = query.trim().toLowerCase();
    if (!q) return [];
    const qs = q.replace(/_/g, ' ');
    const out = [];
    const seen = new Set();
    for (const cat of allCategories()) {
        if (!negative && cat.section === 'negative') continue;
        if (cat.section === 'nsfw' && !state.nsfwMode) continue;
        for (const t of cat.tags) {
            const en = t.prompt.toLowerCase();
            const ens = en.replace(/_/g, ' ');
            const jp = t.japanese.toLowerCase();
            let score = ens.startsWith(qs) ? 0 : jp.startsWith(q) ? 1
                : ens.includes(qs) ? 2 : jp.includes(q) ? 3 : -1;
            if (score < 0) continue;
            const key = en + '|' + cat.section;
            if (seen.has(key)) continue;
            seen.add(key);
            if (isFavTag(cat.id, t.prompt)) score -= 0.5;
            out.push({ score, cat, item: t });
        }
    }
    out.sort((a, b) => a.score - b.score || a.item.prompt.length - b.item.prompt.length);
    return out.slice(0, limit);
}

function attachSuggest(input, negative) {
    if (!input || !input.parentElement) return;
    const list = document.createElement('ul');
    list.className = 'suggest-list';
    list.id = `${input.id}-suggest`;
    list.setAttribute('role', 'listbox');
    list.hidden = true;
    input.parentElement.appendChild(list);
    input.setAttribute('role', 'combobox');
    input.setAttribute('aria-autocomplete', 'list');
    input.setAttribute('aria-expanded', 'false');
    input.setAttribute('aria-controls', list.id);
    input.setAttribute('autocomplete', 'off');

    let items = [], active = -1;
    const tokenStart = () => input.value.lastIndexOf(',') + 1;

    const close = () => {
        list.hidden = true;
        items = []; active = -1;
        input.setAttribute('aria-expanded', 'false');
        input.removeAttribute('aria-activedescendant');
    };
    const render = () => {
        list.innerHTML = '';
        items.forEach((c, i) => {
            const li = document.createElement('li');
            li.id = `${list.id}-${i}`;
            li.setAttribute('role', 'option');
            li.setAttribute('aria-selected', i === active ? 'true' : 'false');
            li.className = 'suggest-item' + (i === active ? ' active' : '');
            const jp = document.createElement('span');
            jp.className = 'suggest-jp';
            jp.textContent = (isFavTag(c.cat.id, c.item.prompt) ? '★ ' : '') + c.item.japanese;
            const en = document.createElement('span');
            en.className = 'suggest-en';
            en.textContent = c.item.prompt;
            const ct = document.createElement('span');
            ct.className = 'suggest-cat';
            ct.textContent = c.cat.name;
            li.appendChild(jp); li.appendChild(en); li.appendChild(ct);
            li.addEventListener('mousedown', (e) => e.preventDefault()); // keep focus
            li.addEventListener('click', () => accept(i));
            list.appendChild(li);
        });
        if (active >= 0) input.setAttribute('aria-activedescendant', `${list.id}-${active}`);
        else input.removeAttribute('aria-activedescendant');
    };
    const update = () => {
        const tok = input.value.slice(tokenStart()).trim();
        if (!tok || /^[<(\[{]/.test(tok)) { close(); return; }
        items = suggestCandidates(tok, negative);
        active = -1;
        if (items.length === 0) { close(); return; }
        list.hidden = false;
        input.setAttribute('aria-expanded', 'true');
        render();
    };
    // picking a candidate adds it right away (with its category)
    const accept = (i) => {
        const c = items[i];
        if (!c) return;
        const pool = negative ? state.negativeTags : selectionTarget(c.cat);
        if (!pool.has(c.item.prompt)) {
            pool.set(c.item.prompt, {
                weight: negative ? 1.0 : tagDefault(c.cat, c.item.prompt), locked: false, cat: c.cat.id,
            });
        }
        const before = input.value.slice(0, tokenStart());
        input.value = before ? before.replace(/\s*$/, ' ') : '';
        close();
        refreshOutputs();
        input.focus();
    };

    input.addEventListener('input', update);
    input.addEventListener('blur', () => setTimeout(close, 150));
    input.addEventListener('keydown', (e) => {
        if (list.hidden || items.length === 0) return;
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
            const n = items.length;
            active = e.key === 'ArrowDown' ? (active + 1) % n : (active - 1 + n) % n;
            render();
            e.preventDefault();
        } else if (e.key === 'Enter' && !e.isComposing && e.keyCode !== 229 && active >= 0) {
            e.preventDefault();
            e.stopImmediatePropagation(); // don't also run the plain "add" handler
            accept(active);
        } else if (e.key === 'Tab' && !e.shiftKey && !e.isComposing) {
            e.preventDefault();
            accept(active >= 0 ? active : 0);
        } else if (e.key === 'Escape') {
            e.preventDefault();
            e.stopPropagation();
            close();
        }
    });
}

function resetPresets() {
    if (!confirm('すべてのモデルプリセットを初期値に戻しますか？')) return;
    state.presets = defaultPresets();
    try { localStorage.removeItem(LS.presets); } catch (e) { /* ignore */ }
    renderPresetEditor();
    refreshOutputs();
}

